public class ToolArgumentValidatorTests
{
    [Theory]
    [InlineData("{\"transferAmount\": -50}", "Transfer amount must be positive.")]
    [InlineData("{\"transferAmount\": 1000000}", "Transfer amount exceeds single-transaction ceiling of $10,000.")]
    [InlineData("{}", "Missing required field 'transferAmount'.")]
    public void ValidateTransferParameters_InvalidInputs_ThrowsValidationException(
        string rawJsonArgs,
        string expectedErrorMessage)
    {
        // Arrange
        var validator = new FinancialToolValidator();

        // Act & Assert
        var action = () => validator.ValidateTransferPayload(rawJsonArgs);
        action.Should().Throw<ValidationException>()
              .WithMessage($"*{expectedErrorMessage}*");
    }
}
